<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user,'stock.alertes')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__.'/../../api/database.php'; require_once __DIR__.'/_inventory.php';
$db=Database::getInstance();
$products=$db->fetchAll("SELECT id,bar_code,medicine_name,category,shelf,actual_quantity,seuil,sell_type,expire_date FROM stock WHERE actual_quantity <= seuil OR (expire_date IS NOT NULL AND expire_date <> '' AND STR_TO_DATE(expire_date,'%Y-%m-%d') BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY)) ORDER BY (actual_quantity <= seuil) DESC, STR_TO_DATE(expire_date,'%Y-%m-%d') ASC, medicine_name");
?>
<section class="space-y-5"><header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold text-amber-700">Surveillance</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Alertes de stock</h1><p class="mt-1 text-sm text-slate-600">Produits sous le seuil ou expirant dans les 30 jours.</p></div><a href="<?=inventoryEscape(app_route_url('stock/entrees'))?>" class="rounded-md bg-green-700 px-4 py-2.5 text-sm font-semibold text-white">Réceptionner un produit</a></header>
<div class="overflow-x-auto rounded-md border border-slate-200 bg-white"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Produit</th><th class="px-4 py-3">Catégorie / emplacement</th><th class="px-4 py-3 text-right">Disponible</th><th class="px-4 py-3 text-right">Seuil</th><th class="px-4 py-3">Expiration</th><th class="px-4 py-3">Action</th></tr></thead><tbody class="divide-y divide-slate-100">
<?php if(!$products):?><tr><td colspan="6" class="px-4 py-12 text-center text-slate-500">Aucune alerte active.</td></tr><?php else:foreach($products as $product):$expiredSoon=!empty($product['expire_date'])&&strtotime($product['expire_date'])!==false&&strtotime($product['expire_date'])<=strtotime('+30 days');?><tr><td class="px-4 py-3 font-semibold"><?=inventoryEscape($product['medicine_name'])?><div class="text-xs font-normal text-slate-500">Code <?= (int)$product['bar_code']?></div></td><td class="px-4 py-3 text-slate-600"><?=inventoryEscape($product['category'])?> · <?=inventoryEscape($product['shelf']?:'Sans emplacement')?></td><td class="px-4 py-3 text-right font-semibold text-rose-700"><?=number_format((float)$product['actual_quantity'],2,',',' ')?> <?=inventoryEscape($product['sell_type'])?></td><td class="px-4 py-3 text-right"><?=number_format((float)$product['seuil'],0,',',' ')?></td><td class="px-4 py-3"><?=$expiredSoon?inventoryEscape(date('d/m/Y',strtotime($product['expire_date']))):'—'?></td><td class="px-4 py-3"><a href="<?=inventoryEscape(app_route_url('stock/entrees'))?>?product_id=<?=(int)$product['id']?>" class="text-sm font-medium text-green-800 hover:underline">Ajouter du stock</a></td></tr><?php endforeach;endif;?>
</tbody></table></div></section>